public class Main {
    public static void main(String[] args) {
        long pricePerUnit = 2500000L;
        long unitsSold = 1500L;
        long totalRevenue = pricePerUnit * unitsSold;
        System.out.println("Total Revenue: Rs " + totalRevenue);
    }
}

public class Main {
